"""Debate verdict and evaluation schemas."""
from typing import Any, List, Literal
from pydantic import BaseModel, Field, field_validator


class DebateVerdict(BaseModel):
    """Structured evaluation generated by the Judge node."""

    winner: Literal["proponent", "opponent", "draw"] = Field(
        description="The winning side of the debate or 'draw' if undecided."
    )
    confidence_score: float = Field(
        ge=0.0,
        le=1.0,
        description="Confidence level of the verdict between 0.0 and 1.0.",
    )
    proponent_score: float = Field(
        ge=0.0,
        le=10.0,
        description="Overall argumentative score for the proponent out of 10.",
    )
    opponent_score: float = Field(
        ge=0.0,
        le=10.0,
        description="Overall argumentative score for the opponent out of 10.",
    )
    key_strengths_proponent: List[str] = Field(
        default_factory=list,
        description="Key persuasive points and sound arguments from the proponent.",
    )
    key_strengths_opponent: List[str] = Field(
        default_factory=list,
        description="Key persuasive points and effective counter-rebuttals from the opponent.",
    )
    deciding_factors: List[str] = Field(
        default_factory=list,
        description="Critical arguments or fallacies that influenced the final verdict.",
    )
    synthesis_summary: str = Field(
        description="Comprehensive dialectical synthesis explaining the outcome."
    )

    @field_validator(
        "key_strengths_proponent",
        "key_strengths_opponent",
        "deciding_factors",
        mode="before",
    )
    @classmethod
    def ensure_list(cls, v: Any) -> List[str]:
        if isinstance(v, str):
            lines = [line.strip("- *").strip() for line in v.split("\n") if line.strip("- *").strip()]
            return lines if lines else [v]
        elif isinstance(v, list):
            return [str(item) for item in v]
        return []

